    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "The aim of this second version of our living systematic review is to assess the effectiveness and safety of COVID-19 vaccines through analyses of all currently available randomized clinical trials.",
      "reason": "An explicit objective is stated (assessing effectiveness and safety of COVID-19 vaccines in randomized trials), but the statement is not presented using a question-formulation framework (e.g., PICO) as required by the element."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We included randomized clinical trials with any control group, i.e. vaccine versus placebo, 'active placebo', no intervention, another vaccine aiming at preventing COVID-19, or any other 'active' comparator [8].",
      "reason": "For an intervention review, the planned comparisons are explicitly stated, specifying interventions (any COVID-19 vaccine), comparators (placebo, active placebo, no intervention, another vaccine, or other active comparator) and inclusion of any participant groups."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "We searched for and included randomized clinical trials, irrespective of publication status, year, and language. We included trials with any participant irrespective of prior exposure, age, sex, comorbidities, immune status, and risk group [8]. We included any vaccine aiming to prevent COVID-19 irrespective of dose and duration of administration. We included randomized clinical trials with any control group, i.e. vaccine versus placebo, 'active placebo', no intervention, another vaccine aiming at preventing COVID-19, or any other 'active' comparator [8].",
      "reason": "The manuscript specifies key study characteristics used for eligibility: study design (randomized clinical trials), participant characteristics (broadly inclusive), interventions (any COVID-19 vaccine, any dose/duration), and comparators. However, it does not explicitly state settings or any follow-up requirements as eligibility criteria (follow-up durations appear only in Results), so the full set of study-characteristic eligibility items is only partially reported."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We searched for and included randomized clinical trials, irrespective of publication status, year, and language.",
      "reason": "The review explicitly states eligibility criteria for report characteristics, declaring inclusion irrespective of publication status, year, and language."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information is provided distinguishing exclusion because outcomes were not measured from exclusion because outcome results were not reported in the supplied evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "All included trials assessed a COVID-19 vaccine compared with placebo (n = 32) or a control vaccine not immunogenic towards COVID-19 (n = 3). The included vaccines were based on mRNA ...; viral vectors ...; protein-subunit ...; or inactivated virus ... (Table 5).",
      "reason": "The review specifies the groups used in syntheses (vaccine versus placebo or non-immunogenic control) and categorizes vaccines by type (mRNA, viral vector, protein-subunit, inactivated), linking groupings to the comparisons addressed in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationale for any notable restrictions on study eligibility (e.g., restrictions and their justification) is provided in the supplied evidence; only broad inclusions are stated and protocol is referenced."
    }
  ],
  "confidence": 75
}

