      "element_id": "prisma_2020_10a_e2",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "We used the trial results reported at maximum follow-up for all outcomes.",
      "reason": "The time frame for measurement is specified as the trial-reported maximum follow-up; additional support in text_10 gives the median follow-up range (35 to 92 days)."
    },
