      "element_id": "prisma_2020_10a_e3",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "We used the trial results reported at maximum follow-up for all outcomes. We used intention-to-treat data if provided by the trialists [8].",
      "reason": "The authors state their approach to which results were sought (selecting trial results at maximum follow-up and using intention-to-treat data when provided), thereby stating whether all compatible results were sought and the principle used."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "We used the trial results reported at maximum follow-up for all outcomes. We used intention-to-treat data if provided by the trialists [8].",
      "reason": "When not all possible time points/analyses were used, the process to select results is described (choose the trial-reported maximum follow-up and use intention-to-treat data when available)."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information in the provided evidence about any changes to outcome-domain inclusion, definitions, or importance or rationales for such changes."
    },
    {
