{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "Our primary outcomes were allcause mortality; vaccine efficacy defined by either preventing COVID-19 symptoms plus positive polymerase chain rection (PCR) test, preventing severe COVID-19 symptoms plus positive PCR test, or preventing positive PCR test only; and serious adverse events [10]. Our secondary outcomes were health-related quality of life and adverse events not considered serious [8]. We used the trial results reported at maximum follow-up for all outcomes. We used intention-to-treat data if provided by the trialists [8]. Several exploratory outcomes were predefined in our protocol and will be presented in a subsequent publication [8].",
      "reason": "The manuscript explicitly lists and defines primary and secondary outcomes and mentions exploratory outcomes and use of intention-to-treat and maximum follow-up; however, it does not comprehensively list or define other variables (e.g. full participant characteristics, funding sources) sought across studies—though some trial characteristics are presented elsewhere (see table_5). Therefore reporting is partial."
    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "To assess the potential impact of missing data, we performed sensitivity analyses using 'best-worst' and 'worst-best' analysis [8, 15]. We used intention-to-treat data if provided by the trialists [8].",
      "reason": "The authors describe methods to address missing outcome data (sensitivity analyses and preference for intention-to-treat data), indicating some assumptions/approaches to missing information; however, there is no detailed description of specific assumptions made about other missing or unclear study information (e.g. how unclear participant or intervention data were handled), so the requirement is only partly met."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "This systematic review with meta-analyses was conducted in accordance with the reporting guideline provided in the Preferred Reporting Items for Systematic Reviews and Meta- Analysis (PRISMA) statement [9, 10]. This review was carried out following recommendations outlined in the Cochrane Handbook of Systematic Reviews of Interventions [11]. More details on our methods can be found in our published protocol [8, 12].",
      "reason": "The manuscript cites the PRISMA reporting guideline, the Cochrane Handbook, and the published protocol as the sources guiding methods and data collection, satisfying the conditional requirement to cite the tool(s) used to determine which data items to collect."
    }
  ],
  "confidence": 80
}

